102	void tst_QCborStreamReader::basics()
103	{
104	    QFETCH_GLOBAL(bool, useDevice);
105	    QBuffer buffer;
106	    QCborStreamReader reader;
107	
108	    if (useDevice) {
109	        buffer.open(QIODevice::ReadOnly);
110	        reader.setDevice(&buffer);
111	        QVERIFY(reader.device() != nullptr);
112	    } else {
113	        QCOMPARE(reader.device(), nullptr);
114	    }
115	
116	    QCOMPARE(reader.currentOffset(), 0);
117	    QCOMPARE(reader.bytesAvailable(), 0);
118	    QCOMPARE(reader.lastError(), QCborError::EndOfFile);
119	
120	    QCOMPARE(reader.type(), QCborStreamReader::Invalid);
121	    QVERIFY(!reader.isUnsignedInteger());
122	    QVERIFY(!reader.isNegativeInteger());
123	    QVERIFY(!reader.isByteArray());
124	    QVERIFY(!reader.isString());
125	    QVERIFY(!reader.isArray());
126	    QVERIFY(!reader.isContainer());
127	    QVERIFY(!reader.isMap());
128	    QVERIFY(!reader.isTag());
129	    QVERIFY(!reader.isSimpleType());
130	    QVERIFY(!reader.isBool());
131	    QVERIFY(!reader.isNull());
132	    QVERIFY(!reader.isUndefined());
133	    QVERIFY(!reader.isFloat16());
134	    QVERIFY(!reader.isFloat());
135	    QVERIFY(!reader.isDouble());
136	    QVERIFY(!reader.isValid());
137	    QVERIFY(reader.isInvalid());
138	
139	    QCOMPARE(reader.containerDepth(), 0);
140	    QCOMPARE(reader.parentContainerType(), QCborStreamReader::Invalid);
141	    QVERIFY(!reader.hasNext());
142	    QVERIFY(!reader.next());
143	    QCOMPARE(reader.lastError(), QCborError::EndOfFile);
144	
145	    QVERIFY(reader.isLengthKnown());    // well, it's not unknown
146	    QCOMPARE(reader.length(), ~0ULL);
147	
148	    if (useDevice) {
149	        reader.reparse();
150	        QVERIFY(reader.device() != nullptr);
151	    } else {
152	        reader.addData(QByteArray());
153	        QCOMPARE(reader.device(), nullptr);
154	    }
155	
156	    // nothing changes, we added nothing
157	    QCOMPARE(reader.currentOffset(), 0);
158	    QCOMPARE(reader.bytesAvailable(), 0);
159	    QCOMPARE(reader.lastError(), QCborError::EndOfFile);
160	
161	    QCOMPARE(reader.type(), QCborStreamReader::Invalid);
162	    QVERIFY(!reader.isUnsignedInteger());
163	    QVERIFY(!reader.isNegativeInteger());
164	    QVERIFY(!reader.isByteArray());
165	    QVERIFY(!reader.isString());
166	    QVERIFY(!reader.isArray());
167	    QVERIFY(!reader.isContainer());
168	    QVERIFY(!reader.isMap());
169	    QVERIFY(!reader.isTag());
170	    QVERIFY(!reader.isSimpleType());
171	    QVERIFY(!reader.isBool());
172	    QVERIFY(!reader.isNull());
173	    QVERIFY(!reader.isUndefined());
174	    QVERIFY(!reader.isFloat16());
175	    QVERIFY(!reader.isFloat());
176	    QVERIFY(!reader.isDouble());
177	    QVERIFY(!reader.isValid());
178	    QVERIFY(reader.isInvalid());
179	
180	    QVERIFY(reader.isLengthKnown());    // well, it's not unknown
181	    QCOMPARE(reader.length(), ~0ULL);
182	
183	    QCOMPARE(reader.containerDepth(), 0);
184	    QCOMPARE(reader.parentContainerType(), QCborStreamReader::Invalid);
185	    QVERIFY(!reader.hasNext());
186	    QVERIFY(!reader.next());
187	
188	    reader.clear();
189	    QCOMPARE(reader.device(), nullptr);
190	    QCOMPARE(reader.currentOffset(), 0);
191	    QCOMPARE(reader.lastError(), QCborError::EndOfFile);
192	}
