194	void tst_QCborStreamReader::clear_data()
195	{
196	    QTest::addColumn<QByteArray>("data");
197	    QTest::addColumn<QCborError>("firstError");
198	    QTest::addColumn<int>("offsetAfterSkip");
199	    QTest::newRow("invalid") << QByteArray(512, '\xff') << QCborError{QCborError::UnexpectedBreak} << 0;
